#!/usr/bin/env bash
set -u
echo "== 解包手机端修复 =="
mkdir -p /tmp/xm-mobile && rm -rf /tmp/xm-mobile/site && mkdir -p /tmp/xm-mobile/site
echo '' | base64 -d > /tmp/xm-mobile/u.tgz
tar -xzf /tmp/xm-mobile/u.tgz -C /tmp/xm-mobile/site
echo "== 覆盖到站点 =="
sudo cp -r /tmp/xm-mobile/site/. /var/www/xinmo-site/
echo "== 校验 =="
grep -c 'header-tools > .header-link' /var/www/xinmo-site/assets/css/red.css
grep -c '100dvh' /var/www/xinmo-site/assets/css/ai-assistant.css
echo "== DONE =="
